// Reverse Linked List iteratively in O(N)
let list = AnimatedLinkedList<Int>()
for val in 1...5 {
    list.append(val)
}

func reverseList(_ l: AnimatedLinkedList<Int>) {
    for i in 1..<l.count {
        if let val = l.remove(at: i) {
            l.prepend(val)
        }
    }
}

reverseList(list)
list.traverse()
